"""0928 folder: multi-step chunk-wise Base runs (always16 = every chunk regenerated by Base 16-step; every_2_stepsK = every 2nd chunk regenerated by Base K-step)
+ same-seed Base-70 / Fast references + labelled side-by-sides + README."""
import os, json, shutil, numpy as np, imageio, cv2
S = "/home/hk28965/specwm"; V = S + "/lingbot-world-v2/specwm_out/spec_v0"; D = S + "/paper/0928/item3_exact_ar_speculative/multistep_base_target"; os.makedirs(D + "/side_by_side", exist_ok=True)
T = {"sand_filling_up_jar": "jar", "sandcastle_wave_impact": "castle"}
ARM = {"always16": ("always16_every_chunk_base16", "Every chunk: Base 16-step"), "every_2_steps1": ("every2nd_base1step", "Every 2nd chunk: Base 1 step"),
       "every_2_steps4": ("every2nd_base4step", "Every 2nd chunk: Base 4 steps"), "every_2_steps8": ("every2nd_base8step", "Every 2nd chunk: Base 8 steps"),
       "every_2": ("every2nd_base16step", "Every 2nd chunk: Base 16 steps"), "specstep_n012c9_never": ("exactspec_cfg5_onestep_target", "Exact spec, one-step target"),
       "base70": ("ref_base70_target", "Base-70 (target)"), "never": ("ref_fast_alone", "Fast alone")}
have, info = {}, []
for t, tn in T.items():
    for run, (name, lab) in ARM.items():
        for s in (1234, 4321, 9999):
            src = "%s/%s/%s_s%d" % (V, t, run, s)
            if not os.path.exists(src + "/video.mp4"): continue
            if run in ("base70", "never", "specstep_n012c9_never") and not any(os.path.exists("%s/%s/%s_s%d/video.mp4" % (V, t, r, s)) for r in ("always16", "every_2_steps1")): continue
            if run == "every_2" and not os.path.exists("%s/%s/every_2_steps1_s%d/video.mp4" % (V, t, s)): continue
            dst = "%s/%s_s%d_%s.mp4" % (D, tn, s, name); shutil.copy2(src + "/video.mp4", dst); have[(tn, s, run)] = dst
            j = src + "/spec_v0.json"
            if os.path.exists(j): d = json.load(open(j)); info.append(dict(case="%s_s%d" % (tn, s), arm=name, gen_s=d.get("gen_s"), corrected=d.get("corrected"), steps=d.get("steps"), plan=d.get("plan")))
def sbs(tn, s, runs, out):
    ps = [have.get((tn, s, r)) for r in runs]
    if not all(ps): return False
    Vs = [[np.asarray(f) for f in imageio.get_reader(p)] for p in ps]; n = min(map(len, Vs)); fr = []
    for i in range(n):
        ts = []
        for v, r in zip(Vs, runs):
            x = cv2.resize(v[min(i, len(v) - 1)], (424, 232), interpolation=cv2.INTER_AREA).copy(); cv2.rectangle(x, (0, 0), (424, 26), (0, 0, 0), -1)
            cv2.putText(x, ARM[r][1], (6, 19), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 255, 255), 1, cv2.LINE_AA); ts.append(x)
        fr.append(np.concatenate(ts, 1))
    imageio.mimwrite(out, fr, fps=16, quality=7, macro_block_size=8); return True
made = []
for tn in ("jar", "castle"):
    for s in (1234, 4321, 9999):
        runs = ["base70", "never", "always16"] + (["specstep_n012c9_never"] if (tn, s, "specstep_n012c9_never") in have else [])
        if sbs(tn, s, runs, "%s/side_by_side/%s_s%d_base_fast_always16%s.mp4" % (D, tn, s, "_exactspec" if len(runs) == 4 else "")): made.append("%s_s%d always16" % (tn, s))
    if sbs(tn, 1234, ["base70", "every_2_steps1", "every_2_steps4", "every_2_steps8", "every_2"], "%s/side_by_side/%s_s1234_base_step_sweep_1_4_8_16.mp4" % (D, tn)): made.append("%s step sweep" % tn)
rows = "\n".join("| %s | %s | %s | %s | %s |" % (r["case"], r["arm"], r["steps"], r["corrected"], "%.0f s" % r["gen_s"] if r["gen_s"] else "–") for r in sorted(info, key=lambda r: (r["case"], r["arm"])))
open(D + "/README.md", "w").write("""# Multi-step chunk-wise Base (the "Base several steps" experiments)

Question: if the target is Base with several denoising steps per chunk instead of one step, does it stop collapsing?
File names `<task>_s<seed>_<arm>.mp4`; same start image, same camera trajectory, empty prompt for every arm.

| arm | what it is |
|---|---|
| always16_every_chunk_base16 | every chunk after chunk 0 regenerated by Base with 16-step RePaint (full CFG) on the whole prefix — the multi-step counterpart of the one-step "target only" null arm (9/24, "quality ceiling") |
| every2nd_base{1,4,8,16}step | every 2nd chunk regenerated by Base with 1 / 4 / 8 / 16 steps, the other chunks are Fast (9/22 step sweep) |
| exactspec_cfg5_onestep_target | the exact speculative sampler with the one-step CFG-5 target, same seed, for contrast |
| ref_base70_target, ref_fast_alone | Base-70 and Fast alone, same seed |

`side_by_side/`: `<task>_s<seed>_base_fast_always16[_exactspec].mp4` (Base | Fast | always16 [| exact spec]); `<task>_s1234_base_step_sweep_1_4_8_16.mp4` (Base | 1 | 4 | 8 | 16 Base steps).

What to look for: with 16 steps the colour stays stable (no wash-out; jar flicker 8.6, lower than Base's 13.9), but the camera does not turn (jar stays centred while Base-70 turns to the table and wall) and chunk boundaries jump 3–8x more than inside chunks; fewer steps bring back exposure flicker, haze and colour drift.

| case | arm | Base steps | chunks corrected | time per clip |
|---|---|---|---|---|
%s
""" % rows)
print("videos", len(have), made)
